package code

import (
	"os"
	"path/filepath"
	"testing"
	"time"

	"cogentcore.org/core/base/iox/imagex"
	"cogentcore.org/core/core"
	"cogentcore.org/core/styles"
	"cogentcore.org/core/styles/abilities"
	"cogentcore.org/core/styles/states"
	"cogentcore.org/core/styles/units"
	"github.com/stretchr/testify/assert"
)

// TestCodeGeneratedReadOnly tests that an editor showing a generated file
// is read-only, and is editable again when it shows another file, and that
// it loses the focused state when another editor gets the focus.
func TestCodeGeneratedReadOnly(t *testing.T) {
	tmp := t.TempDir()
	path := func(name string) string { return filepath.Join(tmp, name) }
	os.WriteFile(path("gen.go"), []byte("// Code generated by test. DO NOT EDIT.\n\npackage a\n"), 0644)
	os.WriteFile(path("a.go"), []byte("package a\n"), 0644)
	os.WriteFile(path("b.txt"), []byte("b text\n"), 0644)
	b := core.NewBody()
	b.Styler(func(s *styles.Style) { s.Min.Set(units.Dp(1200), units.Dp(800)) })
	cv := NewCode(b)
	cv.Defaults()
	cv.ProjectRoot = core.Filename(tmp)
	cv.Settings.ProjectRoot = core.Filename(tmp)
	imagex.UpdateTestImages = true
	defer func() { imagex.UpdateTestImages = false }()
	b.AssertRender(t, "generated-read-only", func() {
		b.AsyncLock()
		cv.ViewFileInIndex(path("b.txt"), 1)
		cv.ViewFileInIndex(path("gen.go"), 0)
		ed0, ed1 := cv.EditorByIndex(0), cv.EditorByIndex(1)
		b.AsyncUnlock()
		editable := func(ed *TextEditor) bool {
			b.AsyncLock()
			defer b.AsyncUnlock()
			return !ed.IsReadOnly() && ed.AbilityIs(abilities.Focusable)
		}
		waitCode(t, 3*time.Second, "generated file read-only", func() bool { return !editable(ed0) })

		b.AsyncLock()
		ed0.SetFocus()
		cv.SetActiveEditorIndex(1)
		b.AsyncUnlock()
		waitCode(t, 3*time.Second, "editor 1 focused", func() bool {
			b.AsyncLock()
			defer b.AsyncUnlock()
			return ed1.StateIs(states.Focused)
		})
		b.AsyncLock()
		assert.False(t, ed0.StateIs(states.Focused), "read-only editor still focused")
		b.AsyncUnlock()

		// another file in the same editor, as with Control+X Control+O
		b.AsyncLock()
		cv.ViewFileInIndex(path("a.go"), 0)
		b.AsyncUnlock()
		waitCode(t, 3*time.Second, "editable file editable", func() bool { return editable(ed0) })
	})
}
